import * as THREE from 'three';
import { createScene } from '/root/data/object.js';

function ensureTriangulated(geom) {
  const g = geom.index ? geom.toNonIndexed() : geom.clone();
  return g;
}

function bakeGeometry(geometry, matrix) {
  const g = ensureTriangulated(geometry);
  g.applyMatrix4(matrix);
  return g;
}

function meshToOBJ(mesh, matrixWorld, state) {
  const geo = mesh.geometry;
  if (!geo || !geo.attributes.position) return;
  const baked = bakeGeometry(geo, matrixWorld);
  const pos = baked.getAttribute('position');
  const norm = baked.getAttribute('normal');

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    state.v.push(`v ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}`);
  }
  if (norm) {
    for (let i = 0; i < norm.count; i++) {
      const x = norm.getX(i), y = norm.getY(i), z = norm.getZ(i);
      state.vn.push(`vn ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}`);
    }
  }
  const vertexOffset = state.vertexCount;
  const normalOffset = state.normalCount;
  const faceCount = pos.count / 3;
  for (let f = 0; f < faceCount; f++) {
    const a = vertexOffset + f * 3 + 1;
    const b = vertexOffset + f * 3 + 2;
    const c = vertexOffset + f * 3 + 3;
    if (norm) {
      const na = normalOffset + f * 3 + 1;
      const nb = normalOffset + f * 3 + 2;
      const nc = normalOffset + f * 3 + 3;
      state.f.push(`f ${a}//${na} ${b}//${nb} ${c}//${nc}`);
    } else {
      state.f.push(`f ${a} ${b} ${c}`);
    }
  }
  state.vertexCount += pos.count;
  if (norm) state.normalCount += norm.count;
}

function traverseExport(object, parentMatrix, state, rotFix) {
  const localMatrix = object.matrix.clone();
  const worldMatrix = parentMatrix.clone().multiply(localMatrix);
  if (object.isMesh) {
    const finalMatrix = rotFix.clone().multiply(worldMatrix);
    meshToOBJ(object, finalMatrix, state);
  } else if (object.isInstancedMesh) {
    const m = new THREE.Matrix4();
    for (let i = 0; i < object.count; i++) {
      object.getMatrixAt(i, m);
      const finalMatrix = rotFix.clone().multiply(worldMatrix).multiply(m);
      meshToOBJ(object, finalMatrix, state);
    }
  }
  for (const child of object.children || []) traverseExport(child, worldMatrix, state, rotFix);
}

const root = createScene();
root.updateMatrixWorld(true);
const rotFix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
const state = { v: [], vn: [], f: [], vertexCount: 0, normalCount: 0 };
traverseExport(root, new THREE.Matrix4(), state, rotFix);

const out = [];
out.push('# Exported from Three.js scene');
out.push(...state.v);
out.push(...state.vn);
out.push(...state.f);
fs.mkdirSync('/root/output', { recursive: true });
fs.writeFileSync('/root/output/object.obj', out.join('\n') + '\n');
console.log(`Wrote /root/output/object.obj with ${state.vertexCount} vertices and ${state.f.length} faces.`);
"}
